-- Generated from reviewed JSON. Apply only after supabase_station_content_v2.sql.
begin;
do $station_release$
declare
  v_release_id uuid;
  v_release_status text;
  v_created_by uuid;
  v_is_admin boolean;
  v_item_count integer;
  v_invalid_day_count integer;
begin
  v_created_by := auth.uid();
  if v_created_by is null then
    select p.id into v_created_by from public.profiles p where p.role = 'admin' order by p.id limit 1;
  end if;
  select exists(select 1 from public.profiles p where p.id = v_created_by and p.role = 'admin') into v_is_admin;
  if v_created_by is null or not coalesce(v_is_admin, false) then
    raise exception 'station_release_import_requires_admin_profile';
  end if;
  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g7-st3-2026.1', 7, 'g7_st3', 'Lớp 7 - Trạm 3: Cảm ứng, sinh trưởng và sinh sản', 'draft', 'Nội dung soạn theo các Bài 33–42 của SGK KHTN 7 Kết nối tri thức; chờ duyệt nội dung và thử giao diện trước khi phát hành.', v_created_by)
  on conflict (version) do update set
    title = case when station_content_releases.status = 'draft' then excluded.title else station_content_releases.title end,
    notes = case when station_content_releases.status = 'draft' then excluded.notes else station_content_releases.notes end,
    updated_at = case when station_content_releases.status = 'draft' then now() else station_content_releases.updated_at end
  returning id into v_release_id;
  select status into v_release_status from public.station_content_releases where id = v_release_id for update;
  if v_release_status <> 'draft' then raise exception 'release_version_is_immutable'; end if;
  delete from public.station_content_items where release_id = v_release_id;
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st3', 1, 1, 'quiz', 'Chọn đáp án chính xác', 'Nêu khái niệm cảm ứng và nhận biết các phản ứng với kích thích ở sinh vật.', '{"question":"Hiện tượng nào thể hiện cảm ứng ở thực vật?","options":["Ngọn cây hướng về phía ánh sáng","Hạt có màu nâu","Thân cây chứa mạch gỗ","Rễ có nhiều tế bào"],"hint":"Cảm ứng là phản ứng với kích thích."}'::jsonb, '{"value":"Ngọn cây hướng về phía ánh sáng","explanation":"Ngọn cây đổi hướng sinh trưởng khi nhận ánh sáng là biểu hiện cảm ứng."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 33. Cảm ứng ở sinh vật và tập tính ở động vật"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st3', 1, 2, 'match', 'Nối khái niệm với đặc điểm', 'Nêu khái niệm cảm ứng và nhận biết các phản ứng với kích thích ở sinh vật.', '{"leftItems":["Ánh sáng","Ngọn cây hướng sáng","Cảm ứng"],"rightItems":["Khả năng tiếp nhận và đáp ứng kích thích","Phản ứng của cây","Kích thích từ môi trường"],"hint":"“Ánh sáng” tương ứng với “Kích thích từ môi trường”."}'::jsonb, '{"value":[{"left":"Ánh sáng","right":"Kích thích từ môi trường"},{"left":"Ngọn cây hướng sáng","right":"Phản ứng của cây"},{"left":"Cảm ứng","right":"Khả năng tiếp nhận và đáp ứng kích thích"}],"explanation":"Ánh sáng: Kích thích từ môi trường; Ngọn cây hướng sáng: Phản ứng của cây; Cảm ứng: Khả năng tiếp nhận và đáp ứng kích thích."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 33. Cảm ứng ở sinh vật và tập tính ở động vật"}]'::jsonb);
