  values(v_release_id, 7, 'g7_st3', 1, 3, 'fill', 'Hoàn thiện kiến thức', 'Nêu khái niệm cảm ứng và nhận biết các phản ứng với kích thích ở sinh vật.', '{"sentence":"Khả năng sinh vật tiếp nhận và phản ứng với kích thích gọi là [blank].","hint":"Từ cần điền gồm 2 tiếng và bắt đầu bằng chữ “c”."}'::jsonb, '{"value":"cảm ứng","explanation":"Từ cần điền là “cảm ứng”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 33. Cảm ứng ở sinh vật và tập tính ở động vật"}]'::jsonb);
