  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 7, 'g7_st3', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Nêu tác động của các yếu tố môi trường đến sinh sản và mối liên hệ các quá trình sống.', '{"textWithBlanks":"Cơ thể sinh vật hoạt động như một thể [blank].","bankWords":["thống nhất","tách rời","bất biến"],"hint":"Từ cần chọn gồm 2 tiếng và bắt đầu bằng chữ “t”."}'::jsonb, '{"value":"thống nhất","explanation":"Từ đúng là “thống nhất”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 7 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 41. Một số yếu tố ảnh hưởng và điều hoà, điều khiển sinh sản ở sinh vật; Bài 42. Cơ thể sinh vật là một thể thống nhất"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
